.art-palms i:nth-child(3){right:12%;height:56%;transform:rotate(-2deg)}
.art-palms i:nth-child(4){right:4%;height:38%;transform:rotate(3deg)}
.art-car{position:absolute;bottom:10%;left:16%;width:116px;height:34px;background:linear-gradient(180deg,#ff9d5a,#d54d35);border-radius:50% 50% 14px 14px;transform:skewX(-8deg);box-shadow:0 10px 22px rgba(0,0,0,.45)}
.art-car:before{content:"";position:absolute;left:22px;right:28px;top:-15px;height:19px;background:linear-gradient(180deg,#25353b,#0d1b20);border-radius:12px 16px 0 0;transform:skewX(8deg)}
.art-car span{position:absolute;bottom:-7px;left:18px;width:20px;height:20px;border-radius:50%;background:#081115;border:3px solid #27383c;box-shadow:62px 0 0 -3px #081115,62px 0 0 0 #27383c}
.art-car:after{content:"";position:absolute;right:6px;top:8px;width:12px;height:6px;background:#ffe1a0;border-radius:2px;box-shadow:0 0 12px #ffd27a}
.art-badge{position:absolute;top:12px;left:12px;padding:6px 9px;background:rgba(3,10,14,.7);border:1px solid rgba(255,255,255,.18);border-radius:5px;font-size:7px;letter-spacing:.2em;color:#dbe6e7;line-height:1.5;backdrop-filter:blur(4px)}
