.edition-body{padding:14px 16px 16px}
.edition-top{display:flex;align-items:center;gap:6px;font-size:7.5px;letter-spacing:.24em;font-weight:800;color:var(--gold)}
.edition-body h3{font-family:var(--font-display);font-size:24px;letter-spacing:.03em;line-height:1;margin:7px 0 6px;font-weight:700}
