.menu-foot{position:relative;z-index:4;height:46px;padding:0 28px;display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid rgba(255,255,255,.08);background:rgba(3,9,13,.72);backdrop-filter:blur(8px)}
.foot-hints{display:flex;gap:14px;font-size:8px;color:#8ea2a6;font-weight:700;letter-spacing:.06em}
.foot-hints span{display:flex;align-items:center;gap:5px}
