.vitals{display:flex;flex-direction:column;gap:3px;width:150px;margin-top:2px}
.vital{display:flex;align-items:center;gap:5px;height:8px}
.vital svg{width:9px;height:9px;flex:none;color:#cfdcdd}
.v-heart{color:#ff8d8d !important}
.v-shield{color:#8fd2ff !important}
.v-bolt{color:#ffe083 !important}
.vital-bar{flex:1;height:3px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.12);overflow:hidden;border-radius:2px}
.vital-bar i{display:block;height:100%;background:linear-gradient(90deg,#ff5f5f,#ff9d7a);transition:width .2s}
