.speedo{display:flex;align-items:center;gap:9px;padding:6px 12px 6px 6px;background:linear-gradient(90deg,rgba(5,14,19,.55),rgba(5,14,19,.92));border:1px solid rgba(255,255,255,.13);border-radius:9px;backdrop-filter:blur(7px)}
