  { id: 'porto',    name: 'PORTO VELHO',           x: -160, z: 640, color: '#9aa7a3' },
  { id: 'jardim',   name: 'JARDIM DAS PALMEIRAS',  x: 250, z: -620, color: '#8fb08a' },
