334:   setGun(v) { if (this.parts.gun) this.parts.gun.visible = v; }
335: 
336:   update(dt, speed = 0, state = 'idle') {
337:     this.flashTimer = Math.max(0, this.flashTimer - dt);
338:     if (this.flashTimer <= 0) {
339:       for (const m of this.materials) if (m.emissive && m.emissive.getHex() !== 0) m.emissive.setHex(0x000000);
340:     }
341:     const sp = Math.min(1, speed / 4.5);
342:     this.walkPhase += dt * (3.2 + speed * 1.5);
343:     const swing = Math.sin(this.walkPhase) * 0.7 * sp;
344:     if (this.parts.legL) {
345:       this.parts.legL.rotation.x = swing;
346:       this.parts.legR.rotation.x = -swing;
347:     } else if (this.parts.l1) {
348:       this.parts.l1.rotation.x = swing * 0.7;
349:       this.parts.l2.rotation.x = -swing * 0.7;
350:     }
351:     if (this.parts.armL) {
352:       this.parts.armL.rotation.x = -swing * 0.75;
353:       if (state === 'aim') {
354:         this.parts.armR.rotation.x = -1.5;
355:         this.parts.armL.rotation.x = -1.25;
356:         this.parts.armL.rotation.z = 0.45;
357:         this.parts.gun.visible = true;
358:       } else if (state === 'shoot') {
359:         this.parts.armR.rotation.x = -1.62;
360:         this.parts.armL.rotation.x = -1.3;
361:         this.parts.gun.visible = true;
362:       } else {
363:         this.parts.armR.rotation.x = swing * 0.75;
364:         this.parts.armL.rotation.z = 0;
365:         this.parts.gun.visible = false;
366:       }
367:     } else if (this.parts.a1) {
368:       this.parts.a1.rotation.x = swing * 0.6;
369:       this.parts.a2.rotation.x = -swing * 0.6;
370:     }
371:     const bob = state === 'idle' ? Math.sin(this.walkPhase * 0.5) * 0.012 : Math.abs(Math.sin(this.walkPhase)) * 0.035 * sp;
372:     if (this.parts.hips) this.parts.hips.position.y = 0.94 + bob;
373:     else if (this.parts.torso) this.parts.torso.position.y = 1.22 + bob;
374:     if (this.parts.head) this.parts.head.position.y = 1.72 + bob * 0.6;
375:   }
376: 
377:   flash() {
378:     this.flashTimer = 0.09;
379:     for (const m of this.materials) if (m.emissive) m.emissive.setHex(0x661111);
380:   }
381: 
382:   dispose() {
383:     this.group.traverse(o => {
384:       if (o.geometry) o.geometry.dispose();
385:       if (o.material) {
386:         if (Array.isArray(o.material)) o.material.forEach(m => m.dispose());
387:         else o.material.dispose();
388:       }
389:     });
390:   }
391: }
