import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const url = process.env.URL || 'http://127.0.0.1:4173/';
const out = '/tmp/opencode/shots';
import { mkdirSync } from 'node:fs';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE', m.text()); } });
page.on('response', (r) => { if (r.status() >= 400) console.log('HTTP', r.status(), r.url()); });

await page.goto(url, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1500);
await page.screenshot({ path: `${out}/01-boot.png` });
await page.waitForTimeout(3000);
await page.screenshot({ path: `${out}/02-menu.png` });
console.log('menu visible', await page.locator('#main-menu').isVisible());
console.log('game?', await page.evaluate(() => !!window.__game));

await page.locator('[data-menu="play"]').click();
await page.waitForTimeout(700);
await page.screenshot({ path: `${out}/03-charselect.png` });
await page.locator('.cs-card.luiza').click();
await page.waitForTimeout(2500);
await page.screenshot({ path: `${out}/04-game.png` });
console.log('state', await page.evaluate(() => {
  const g = window.__game;
  return g ? { mode: g.mode, char: g.player?.charId, pos: g.player?.pos, hud: !document.getElementById('hud').classList.contains('hidden'), fps: g.fps, enemies: g.enemies.length, vehicles: g.vehicles.length } : null;
}));

// walk forward and look
await page.keyboard.down('KeyW');
await page.waitForTimeout(1200);
await page.keyboard.up('KeyW');
await page.mouse.move(720, 450);
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/05-walk.png` });

// map
await page.keyboard.press('KeyM');
await page.waitForTimeout(600);
await page.screenshot({ path: `${out}/06-map.png` });
console.log('map open', await page.locator('#map-overlay').isVisible());
await page.keyboard.press('Escape');
await page.waitForTimeout(400);

// pause
await page.keyboard.press('Escape');
await page.waitForTimeout(600);
await page.screenshot({ path: `${out}/07-pause.png` });
console.log('pause open', await page.locator('#pause-menu').isVisible());
await page.keyboard.press('Escape');
await page.waitForTimeout(400);

// start mission via game API
await page.evaluate(() => window.__game.startMissionById('m1'));
await page.waitForTimeout(3500);
await page.screenshot({ path: `${out}/08-mission.png` });
console.log('mission', await page.evaluate(() => {
  const g = window.__game;
  return { mission: g.mission?.def?.id, step: g.mission?.step, dialog: g.dialogueActive, objective: document.getElementById('obj-text').textContent };
}));

// mobile
const mp = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
mp.on('pageerror', (e) => console.log('MOBILE PAGEERROR', e.message));
await mp.goto(url, { waitUntil: 'load', timeout: 60000 });
await mp.waitForTimeout(4500);
await mp.screenshot({ path: `${out}/09-mobile-menu.png` });
await mp.locator('[data-menu="play"]').click();
await mp.waitForTimeout(500);
await mp.screenshot({ path: `${out}/10-mobile-char.png` });
await mp.locator('.cs-card.luiza').click();
await mp.waitForTimeout(2500);
await mp.screenshot({ path: `${out}/11-mobile-game.png` });
console.log('mobile touch', await mp.evaluate(() => ({ touch: document.body.classList.contains('touch-mode'), hud: !document.getElementById('hud').classList.contains('hidden') })));

console.log('ERRORS', errors.length, errors.slice(0, 10));
await browser.close();

