.pm-row.available em{color:var(--gold)}
.pause-tip{margin-top:18px;font-size:9px;line-height:1.55;color:#93a8ab;padding:11px 13px;background:rgba(46,230,200,.05);border:1px solid rgba(46,230,200,.15);border-radius:5px}
.pause-tip span{color:var(--teal);font-weight:800;font-size:7px;letter-spacing:.18em;margin-right:5px}
.pause-save{margin-top:14px;font-size:7px;color:#61777b;letter-spacing:.06em}
.pause-save span{color:var(--green)}

