   MODALS
   ============================================================ */
.modal{flex-direction:column;align-items:stretch;justify-content:stretch;width:min(1040px,94vw);height:min(760px,92vh);margin:auto;background:linear-gradient(180deg,rgba(7,17,23,.98),rgba(4,11,16,.99));border:1px solid rgba(255,255,255,.14);border-radius:10px;box-shadow:0 40px 120px rgba(0,0,0,.8);overflow:hidden;animation:modalIn .3s cubic-bezier(.2,.8,.2,1)}
@keyframes modalIn{from{opacity:0;transform:translateY(16px) scale(.99)}to{opacity:1;transform:none}}
.modal-head{display:flex;align-items:center;justify-content:space-between;padding:18px 22px 14px;border-bottom:1px solid rgba(255,255,255,.1);flex:none}
.modal-head small{font-size:6.5px;letter-spacing:.26em;color:var(--teal);font-weight:800}
.modal-head h2{font-family:var(--font-display);font-size:30px;letter-spacing:.05em;line-height:1;margin-top:2px}
.modal-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 22px;border-top:1px solid rgba(255,255,255,.1);flex:none;background:rgba(0,0,0,.15)}
.modal-foot-right{display:flex;align-items:center;gap:12px}
.save-note{font-size:7.5px;color:#6f868a;letter-spacing:.04em}

.settings-grid{flex:1;display:grid;grid-template-columns:190px 1fr;min-height:0}
.settings-tabs{border-right:1px solid rgba(255,255,255,.1);padding:14px 10px;display:flex;flex-direction:column;gap:2px;background:rgba(255,255,255,.015)}
.settings-tabs button{text-align:left;padding:10px 13px;border-radius:5px;font-size:10px;font-weight:700;color:#a6b8bb;border-left:2px solid transparent}
.settings-tabs button:hover{background:rgba(255,255,255,.06);color:#fff}
.settings-tabs button.active{background:rgba(255,196,107,.1);color:var(--gold);border-left-color:var(--gold)}
.settings-content{overflow:auto;padding:18px 24px}
.settings-page{display:none}
.settings-page.active{display:block;animation:fadeIn .2s ease}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.setting-group{margin-bottom:22px}
.setting-group h3{font-size:7px;letter-spacing:.24em;color:#8ba0a4;font-weight:800;margin-bottom:5px;padding-bottom:6px;border-bottom:1px solid rgba(255,255,255,.07)}
.setting-row{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:9px 0;border-bottom:1px solid rgba(255,255,255,.045)}
.setting-row:last-child{border:0}

