81:     if (p >= target - 0.5) {
82:       status.textContent = stages[Math.min(i, stages.length - 1)][1];
83:       i++;
84:     }
85:     if (bar) bar.style.width = p + '%';
86:     if (pct) pct.textContent = Math.round(p) + '%';
87:     if (p >= 100) {
88:       clearInterval(tick);
89:       setTimeout(() => {
90:         bootDone = true;
91:         $('boot').classList.add('hidden');
92:         showMainMenu();
93:       }, 520);
94:     }
95:   }, 55);
96: }
