input.content:
import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const out = '/tmp/opencode/shots2';
mkdirSync(out, { recursive: true });
const URL = 'http://127.0.0.1:4173/';
const SET = { quality: 'medium', resScale: 70, shadows: false, water: 'medium', distance: 70, showFps: true, touch: 'auto' };
const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });

function attach(page, tag) {
  page.setDefaultTimeout(90000);
  page.on('pageerror', e => console.log(`[${tag}] PAGEERROR`, e.message));
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') console.log(`[${tag}] ${m.type().toUpperCase()}`, m.text().slice(0, 500)); });
}

async function boot(page, settings) {
  await page.addInitScript((s) => {
    localStorage.setItem('matteo5.settings.v1', JSON.stringify(s));
    localStorage.removeItem('matteo5.save.v1');
  }, settings);
  await page.goto(URL, { waitUntil: 'load' });
  await page.locator('#main-menu:not(.hidden)').waitFor({ state: 'visible' });
  await page.locator('[data-menu="play"]').click();
  await page.waitForTimeout(300);
  await page.locator('.cs-card.luiza').click();
  await page.waitForTimeout(2400);
  await page.locator('#tut-start').click().catch(() => {});
  await page.waitForTimeout(900);
}

// ---------- desktop ----------
const d = await browser.newPage({ viewport: { width: 1440, height: 900 } });
attach(d, 'desktop');
await boot(d, SET);
console.log('desktop state', await d.evaluate(() => {
  const g = window.__game;
  return { mode: g.mode, fps: Math.round(g.fps), cam: { x: +g.camera.position.x.toFixed(1), y: +g.camera.position.y.toFixed(1), z: +g.camera.position.z.toFixed(1) }, pitch: +g._camPitch.toFixed(2) };
}));
// Look at the sea for a water screenshot.
await d.evaluate(() => {
  const g = window.__game;
  g.player.pos.set(646, 0, 10); g.player.yaw = Math.PI / 2; g._camYaw = Math.PI / 2; g._camPitch = 0.12;
  g._placePlayer(); g._snapCamera();
});
await d.waitForTimeout(1200);
await d.screenshot({ path: `${out}/desktop-water.png` });
// Map
await d.keyboard.press('KeyM');
await d.waitForTimeout(600);
console.log('map', await d.evaluate(() => ({
  open: window.__game.mapOpen,
  zoom: document.getElementById('map-zoom-level').textContent,
  playerVisible: getComputedStyle(document.getElementById('map-player')).display,
  transform: document.getElementById('map-player').style.transform
})));
await d.screenshot({ path: `${out}/desktop-map.png` });
await d.locator('#map-zoom-in').click();
await d.waitForTimeout(300);
console.log('map zoom after +', await d.locator('#map-zoom-level').textContent());
await d.keyboard.press('Escape');
await d.waitForTimeout(300);
// Minimap crop
const mm = await d.locator('#minimap-wrap').boundingBox();
await d.screenshot({ path: `${out}/desktop-minimap.png`, clip: mm });

// ---------- mobile portrait ----------
const m = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
attach(m, 'mobile');
await boot(m, { ...SET, resScale: 55, touch: 'on', quality: 'low', water: 'low' });
const layout = await m.evaluate(() => {
  const r = (id) => { const e = document.getElementById(id); if (!e) return null; const b = e.getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height), vis: !e.classList.contains('hidden') && getComputedStyle(e).display !== 'none' }; };
  return {
    touch: document.body.classList.contains('touch-mode'),
    hud: !document.getElementById('hud').classList.contains('hidden'),
    touchControls: r('touch-controls'),
    minimap: r('minimap-wrap'),
    status: r('mobile-status'),
    joystick: r('joystick'),
    actions: r('touch-actions'),
    objective: r('objective-panel'),
    mapBtn: r('tbtn-map'),
    pauseBtn: r('tbtn-pause')
  };
});
console.log('mobile layout', JSON.stringify(layout, null, 1));
await m.screenshot({ path: `${out}/mobile-portrait.png` });
// Touch fire hold: pointerdown then check aim true, pointerup then false
const shoot = m.locator('[data-touch="shoot"]');
const sb = await shoot.boundingBox();
await m.touchscreen.tap(sb.x + sb.width / 2, sb.y + sb.height / 2);
await m.waitForTimeout(200);
console.log('touch shoot aim after tap', await m.evaluate(() => window.__game.input.aim));
// Map on mobile
await m.locator('#tbtn-map').click();
await m.waitForTimeout(500);
await m.screenshot({ path: `${out}/mobile-map.png` });
await m.keyboard.press('Escape');
await m.waitForTimeout(300);

// ---------- mobile landscape ----------
const l = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
attach(l, 'landscape');
await boot(l, { ...SET, resScale: 55, touch: 'on', quality: 'low', water: 'low' });
await l.screenshot({ path: `${out}/mobile-landscape.png` });
console.log('landscape', await l.evaluate(() => {
  const r = (id) => { const e = document.getElementById(id); const b = e.getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height) }; };
  return { status: r('mobile-status'), joystick: r('joystick'), actions: r('touch-actions'), objective: r('objective-panel') };
}));

await browser.close();
console.log('DONE');

