import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const out = '/tmp/opencode/shots3';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
page.setDefaultTimeout(90000);
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text().slice(0, 800)); });
await page.addInitScript(() => { localStorage.setItem('matteo5.settings.v1', JSON.stringify({ quality:'medium', resScale:100, shadows:false, water:'high', distance:90, showFps:false })); localStorage.removeItem('matteo5.save.v1'); });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.locator('#main-menu:not(.hidden)').waitFor({ state: 'visible' });
await page.locator('[data-menu="play"]').click();
await page.waitForTimeout(300);
await page.locator('.cs-card.luiza').click();
await page.waitForTimeout(2400);
await page.locator('#tut-start').click().catch(()=>{});
await page.waitForTimeout(700);

async function shot(name, cam, look) {
  await page.evaluate(({ cam, look }) => {
    const g = window.__game;
    g.paused = true;
    document.getElementById('pause-menu').classList.add('hidden');
    document.getElementById('hud').classList.add('hidden');
    document.getElementById('touch-controls')?.classList.add('hidden');
    g.camera.position.set(cam[0], cam[1], cam[2]);
    g.camera.lookAt(look[0], look[1], look[2]);
    g.camera.updateMatrixWorld();
  }, { cam, look });
  await page.waitForTimeout(900);
  await page.screenshot({ path: `${out}/${name}.png` });
}

// High angled view over the bay
await shot('ocean-high', [640, 55, 120], [1100, 0, 0]);
// Mid view, close to the water, looking along the coast
await shot('ocean-mid', [720, 12, 260], [1000, 0, -120]);
// Low view from the pier looking back at the beach
await shot('ocean-low', [780, 4, 146], [640, 2, 60]);
// Straight down for foam bands
await shot('ocean-top', [800, 120, 0], [800, 0, 0.01]);
console.log('done');
await browser.close();

