/* Mobile HUD (only rendered when touch mode is active) */
.mobile-hud{display:none}
body.touch-mode .mobile-hud{display:block;position:absolute;inset:0;pointer-events:none;z-index:3}
.mh-compass{position:absolute;top:calc(9px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);width:clamp(94px,34vw,168px);height:22px;overflow:hidden;mask-image:linear-gradient(90deg,transparent,#000 16%,#000 84%,transparent);opacity:.92}
.mh-compass-strip{position:absolute;left:50%;top:3px;display:flex;align-items:center;gap:12px;transform:translateX(-50%);font-size:6.5px;font-weight:800;letter-spacing:.1em;color:#dce7e8;white-space:nowrap;transition:transform .08s linear}
.mh-compass-strip i{width:1px;height:4px;background:rgba(255,255,255,.35)}
