import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/node_modules/playwright/package.json');
const { chromium } = require('playwright');
const out = '/tmp/opencode/mhud3';
mkdirSync(out, { recursive: true });
const URL = 'http://127.0.0.1:4173/';
const browser = await chromium.launch({
  headless: true,
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist']
});
const ok = (name, cond, extra = '') => console.log(`${cond ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);

async function boot(page, settings, { dismissTutorial = true } = {}) {
  page.setDefaultTimeout(90000);
  page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
  page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.text().slice(0, 300)); });
  await page.addInitScript((s) => {
    localStorage.setItem('matteo5.settings.v1', JSON.stringify(s));
    localStorage.removeItem('matteo5.save.v1');
  }, settings);
  await page.goto(URL, { waitUntil: 'load' });
  await page.locator('#main-menu:not(.hidden)').waitFor({ state: 'visible' });
  await page.locator('[data-menu="play"]').click();
  await page.waitForTimeout(250);
  await page.locator('.cs-card.luiza').click();
  await page.waitForTimeout(2400);
  if (dismissTutorial) await page.locator('#tut-start').click().catch(() => {});
