.touch-controls{position:absolute;inset:0;pointer-events:none;z-index:26;touch-action:none}
.touch-controls button{pointer-events:auto}
.touch-brand{position:absolute;top:calc(8px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);font-family:var(--font-display);font-size:11px;letter-spacing:.16em;color:rgba(234,242,242,.55);pointer-events:none;white-space:nowrap}
.touch-brand span{display:block;font-family:var(--font-ui);font-size:5px;letter-spacing:.28em;color:var(--teal);text-align:center;margin-top:1px;font-weight:800}
.touch-look-hint{position:absolute;right:18px;top:50%;transform:translateY(-50%);font-size:7px;letter-spacing:.2em;font-weight:800;color:rgba(255,255,255,.4);display:flex;align-items:center;gap:6px;pointer-events:none;transition:opacity .5s;text-shadow:0 1px 4px #000}
.touch-look-hint span{font-size:16px;color:rgba(46,230,200,.7)}
.touch-look-hint.hide{opacity:0}
.touch-top{position:absolute;top:calc(12px + env(safe-area-inset-top));right:calc(12px + env(safe-area-inset-right));display:flex;gap:8px;pointer-events:auto;z-index:4}
.touch-mini{width:40px;height:40px;border-radius:11px;background:rgba(3,10,14,.72);border:1px solid rgba(255,255,255,.22);display:grid;place-items:center;color:#dce7e8;backdrop-filter:blur(8px);box-shadow:0 4px 14px rgba(0,0,0,.35)}
.touch-mini:active{background:rgba(255,196,107,.8);color:#1c1108;transform:scale(.94)}
.touch-mini svg{width:18px;height:18px}
.joystick{position:absolute;left:calc(18px + env(safe-area-inset-left));bottom:calc(20px + env(safe-area-inset-bottom));width:118px;height:118px;pointer-events:auto;touch-action:none;transform:scale(var(--touch-scale,1));transform-origin:bottom left}
.stick-base{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(255,255,255,.22);background:radial-gradient(circle at 38% 30%,rgba(255,255,255,.13),rgba(3,10,14,.42) 65%);box-shadow:inset 0 0 26px rgba(0,0,0,.45),0 8px 24px rgba(0,0,0,.35);backdrop-filter:blur(5px)}
.stick-base:before,.stick-base:after{content:"";position:absolute;background:rgba(255,255,255,.12)}
.stick-base:before{left:50%;top:12%;bottom:12%;width:1px}
.stick-base:after{top:50%;left:12%;right:12%;height:1px}
.stick-knob{position:absolute;left:50%;top:50%;width:48px;height:48px;margin:-24px 0 0 -24px;border-radius:50%;background:radial-gradient(circle at 38% 30%,rgba(255,255,255,.5),rgba(255,255,255,.14) 60%,rgba(255,255,255,.06));border:1px solid rgba(255,255,255,.45);box-shadow:0 5px 16px rgba(0,0,0,.45),inset 0 0 10px rgba(255,255,255,.18);transition:transform .06s}
.stick-label{position:absolute;bottom:-14px;left:50%;transform:translateX(-50%);font-size:6px;letter-spacing:.2em;color:rgba(255,255,255,.45);font-weight:800}
.touch-actions{position:absolute;right:calc(10px + env(safe-area-inset-right));bottom:calc(12px + env(safe-area-inset-bottom));width:216px;height:210px;pointer-events:none;transform:scale(calc(var(--touch-base,1) * var(--touch-scale,1)));transform-origin:bottom right}
.tbtn{position:absolute;pointer-events:auto;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;border-radius:50%;background:radial-gradient(circle at 38% 30%,rgba(28,52,60,.72),rgba(4,13,18,.62) 70%);border:1px solid rgba(255,255,255,.26);color:#eaf2f2;backdrop-filter:blur(6px);box-shadow:0 5px 16px rgba(0,0,0,.35),inset 0 0 12px rgba(255,255,255,.05);touch-action:none;user-select:none;-webkit-user-select:none;transition:transform .07s,background .07s,color .07s}
.tbtn:active,.tbtn.pressed{background:rgba(255,196,107,.88);color:#1c1108;transform:scale(.93);box-shadow:0 0 22px rgba(255,196,107,.45)}
.tbtn svg{width:20px;height:20px}
.tbtn small{font-size:5px;letter-spacing:.08em;font-weight:800;opacity:.75;pointer-events:none}
.ps-tri svg{color:#2ee6c8}
.ps-cir svg{color:#ff7a66}
.ps-sq svg{color:#f29ac0}
.ps-cr svg{color:#7fb8ff}
.glyph-tri{width:52px;height:52px;right:58px;top:54px}
.glyph-cir{width:46px;height:46px;right:0;top:110px}
.glyph-sq{width:46px;height:46px;right:116px;top:110px}
.glyph-cr{width:52px;height:52px;right:58px;top:156px}
.tbtn.shoulder{width:58px;height:34px;border-radius:9px;background:linear-gradient(180deg,rgba(20,40,48,.85),rgba(4,13,18,.7))}
.tbtn.shoulder span{font-size:9px;font-weight:800;letter-spacing:.05em}
.tbtn.shoulder small{font-size:4.5px}
.tbtn.shoulder.l2{left:0;top:0}
.tbtn.shoulder.r2{right:0;top:0}
.tbtn.shoulder.r1{right:0;top:42px}
