.map-head-actions{display:flex;align-items:center;gap:6px}
.map-zoom-level{font-family:var(--font-display);font-size:14px;font-weight:700;letter-spacing:.06em;color:var(--gold);min-width:38px;text-align:right;opacity:.9}
.map-body{flex:1;display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:18px;min-height:0}
.map-canvas-wrap{position:relative;background:#08202a;border:1px solid rgba(255,255,255,.14);border-radius:8px;overflow:hidden;display:flex;align-items:center;justify-content:center;min-height:0}
#fullmap{max-width:100%;max-height:100%;width:auto;height:auto;aspect-ratio:1;transition:transform .15s;cursor:grab}
#fullmap:active{cursor:grabbing}
  .rp-jobs{grid-template-columns:1fr;padding:12px 14px}
  .rp-job p{min-height:0}
  .result-card{padding:22px 16px;width:94vw}
