  .result-rewards{grid-template-columns:1fr 1fr}
  .result-actions{flex-wrap:wrap}
  .result-actions .btn{flex:1;min-width:120px;font-size:10px;padding:0 10px}
  .chapter-inner h1{font-size:42px;padding:0 12px}
