.map-side h3{font-size:7px;letter-spacing:.22em;color:#8ba0a4;font-weight:800;margin-bottom:7px}
.map-legend div{display:flex;align-items:center;gap:7px;font-size:9px;color:#c5d3d5;padding:2.5px 0;font-weight:600}
.lg{width:9px;height:9px;border-radius:50%;display:inline-block;flex:none}
.lg.player{background:var(--gold);box-shadow:0 0 6px var(--gold)}
.lg.mission{background:#ffd27a;border:1px solid #fff}
.lg.active{background:var(--teal);box-shadow:0 0 6px var(--teal)}
.lg.police{background:#5cc8ff;box-shadow:0 0 6px #5cc8ff}
