.map-wp{font-size:8px;letter-spacing:.12em;font-weight:800;color:var(--teal);background:rgba(46,230,200,.1);border:1px solid rgba(46,230,200,.3);padding:0 9px;height:34px;display:inline-flex;align-items:center;border-radius:8px}
