264:   _buildSky() {
265:     const geo = new THREE.SphereGeometry(2800, 32, 20);
266:     this.skyUniforms = {
267:       uTop: { value: new THREE.Color('#2a6a8a') },
268:       uHorizon: { value: new THREE.Color('#ffb27d') },
269:       uGlow: { value: new THREE.Color('#ffd7a1') },
270:       uSunDir: { value: this.sunDir.clone() },
271:       uSunColor: { value: new THREE.Color('#fff1cb') },
272:       uNight: { value: 0 },
273:       uTime: { value: 0 }
274:     };
275:     const mat = new THREE.ShaderMaterial({
276:       uniforms: this.skyUniforms,
277:       side: THREE.BackSide,
278:       depthWrite: false,
279:       fog: false,
280:       vertexShader: `
281:         varying vec3 vDir;
282:         void main(){
283:           vDir = normalize(position);
284:           gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0);
285:         }`,
286:       fragmentShader: `
287:         uniform vec3 uTop, uHorizon, uGlow, uSunColor;
288:         uniform vec3 uSunDir;
289:         uniform float uNight, uTime;
290:         varying vec3 vDir;
291:         float hash(vec3 p){ return fract(sin(dot(p, vec3(12.9898,78.233,45.164)))*43758.5453); }
292:         float noise(vec2 p){
293:           vec2 i=floor(p), f=fract(p);
294:           f=f*f*(3.0-2.0*f);
295:           float a=hash(vec3(i,1.0)), b=hash(vec3(i+vec2(1.0,0.0),1.0));
296:           float c=hash(vec3(i+vec2(0.0,1.0),1.0)), d=hash(vec3(i+vec2(1.0,1.0),1.0));
297:           return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);
298:         }
299:         void main(){
300:           vec3 d = normalize(vDir);
301:           float h = clamp(d.y, -0.08, 1.0);
302:           vec3 col = mix(uHorizon, uTop, smoothstep(0.0, 0.38, h));
303:           col = mix(col, uGlow, smoothstep(0.14, -0.03, abs(h)) * 0.24);
304:           float sd = max(dot(d, normalize(uSunDir)), 0.0);
305:           col += uSunColor * pow(sd, 520.0) * 2.2;
306:           col += uSunColor * pow(sd, 9.0) * 0.16;
307:           float cl = noise(d.xz * 3.2 + vec2(uTime*0.004, 0.0)) * 0.6 + noise(d.xz * 7.0 - vec2(uTime*0.002, 0.0)) * 0.4;
308:           float cloud = smoothstep(0.56, 0.84, cl) * smoothstep(0.04, 0.24, h) * (1.0 - smoothstep(0.55, 0.85, h));
309:           vec3 cloudCol = mix(vec3(1.0,0.87,0.74), vec3(0.56,0.66,0.75), uNight*0.7);
310:           col = mix(col, cloudCol, cloud * (0.32 + uNight*0.12));
311:           if (uNight > 0.01) {
312:             float st = hash(floor(d*420.0));
313:             float stars = step(0.9965, st) * smoothstep(0.1, 0.5, h) * (1.0 - smoothstep(0.72, 0.95, h));
314:             stars *= 0.55 + 0.45*sin(uTime*2.2 + st*40.0);
315:             col += vec3(0.85,0.92,1.0) * stars * uNight;
316:             col += vec3(1.0,0.45,0.22) * smoothstep(0.12,0.0,h) * 0.06;
317:           }
318:           gl_FragColor = vec4(col, 1.0);
319:           #include <tonemapping_fragment>
320:           #include <colorspace_fragment>
321:         }`
322:     });
323:     this.sky = new THREE.Mesh(geo, mat);
324:     this.sky.frustumCulled = false;
325:     this.sky.renderOrder = -100;
326:     this.scene.add(this.sky);
