362:   _buildWater() {
363:     const q = this.settings.water || 'medium';
364:     const seg = q === 'high' ? 220 : q === 'low' ? 72 : 144;
365:     const geo = new THREE.PlaneGeometry(2500, 2600, seg, seg);
366:     geo.rotateX(-Math.PI / 2);
367:     this.waterUniforms = {
368:       uTime: { value: 0 },
369:       uSunDir: { value: this.sunDir.clone() },
370:       uSunColor: { value: new THREE.Color('#ffe6b8') },
371:       uDeep: { value: new THREE.Color('#0a4050') },
372:       uShallow: { value: new THREE.Color('#249a9c') },
373:       uFoam: { value: new THREE.Color('#f4f7ee') },
374:       uFog: { value: new THREE.Color('#e9a87e') },
375:       uSkyTop: { value: new THREE.Color('#2a6a8a') },
376:       uSkyHorizon: { value: new THREE.Color('#ffb27d') },
377:       uCamPos: { value: new THREE.Vector3() },
378:       uNight: { value: 0 },
379:       uShoreX: { value: SHORE_X },
380:       uDetail: { value: q === 'low' ? 0.85 : 1.0 }
381:     };
382:     const mat = new THREE.ShaderMaterial({
383:       uniforms: this.waterUniforms,
384:       fog: false,
385:       vertexShader: `
386:         uniform float uTime;
387:         uniform float uDetail;
388:         varying vec3 vWorld;
389:         varying vec3 vNormal;
390:         varying float vWave;
391: 
392:         // Directional swell: long Pacific-style rollers crossing the bay.
393:         float swell(vec2 p, float t){
394:           float h = 0.0;
395:           h += sin(dot(p, vec2( 0.052, 0.031)) + t * 1.05) * 0.180;
396:           h += sin(dot(p, vec2(-0.028, 0.074)) - t * 0.82) * 0.120;
397:           h += sin(dot(p, vec2( 0.016, 0.018)) + t * 0.52) * 0.200;
398:           h += sin(dot(p, vec2( 0.110,-0.090)) + t * 1.55) * 0.035;
399:           h += sin(dot(p, vec2(-0.190, 0.060)) + t * 2.20) * 0.020;
400:           return h;
401:         }
402: 
403:         void main(){
404:           vec3 pos = position;
405:           vec4 wp = modelMatrix * vec4(pos, 1.0);
406:           float t = uTime;
407:           float w = swell(wp.xz, t) * uDetail;
408:           wp.y += w;
409: 
410:           // Analytic-ish normal from finite differences on the swell field.
411:           float e = 1.25;
412:           float hL = swell(wp.xz - vec2(e, 0.0), t) * uDetail;
413:           float hR = swell(wp.xz + vec2(e, 0.0), t) * uDetail;
414:           float hD = swell(wp.xz - vec2(0.0, e), t) * uDetail;
415:           float hU = swell(wp.xz + vec2(0.0, e), t) * uDetail;
416:           vNormal = normalize(vec3((hL - hR) / (2.0 * e), 1.0, (hD - hU) / (2.0 * e)));
417:           vWorld = wp.xyz;
418:           vWave = w;
419:           gl_Position = projectionMatrix * viewMatrix * wp;
420:         }`,
421:       fragmentShader: `
422:         uniform float uTime, uNight, uShoreX, uDetail;
423:         uniform vec3 uSunDir, uSunColor, uDeep, uShallow, uFoam, uFog, uSkyTop, uSkyHorizon, uCamPos;
424:         varying vec3 vWorld;
425:         varying vec3 vNormal;
426:         varying float vWave;
427: 
428:         float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
429:         float noise(vec2 p){
430:           vec2 i = floor(p), f = fract(p);
431:           f = f * f * (3.0 - 2.0 * f);
432:           return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
433:                      mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
434:         }
435:         float fbm(vec2 p){
436:           float v = 0.0, a = 0.5;
437:           for (int i = 0; i < 3; i++) {
438:             v += a * noise(p);
439:             p = p * 2.03 + vec2(17.1, 9.7);
440:             a *= 0.5;
441:           }
442:           return v;
443:         }
444: 
445:         void main(){
446:           vec3 viewDir = normalize(uCamPos - vWorld);
447:           vec3 N = normalize(vNormal);
448: 
449:           // Two scales of moving capillary ripples on top of the swell.
450:           vec2 q = vWorld.xz;
451:           float n1 = fbm(q * 0.30 + vec2(uTime * 0.34, uTime * 0.11));
452:           float n2 = fbm(q * 1.05 - vec2(uTime * 0.58, uTime * 0.24));
453:           vec3 detail = vec3(
454:             (n1 - 0.5) * 0.34 * uDetail + (n2 - 0.5) * 0.13 * uDetail,
455:             0.0,
456:             (n2 - 0.5) * 0.30 * uDetail - (n1 - 0.5) * 0.10 * uDetail
457:           );
458:           N = normalize(N + detail);
459: 
460:           float ndv = clamp(dot(N, viewDir), 0.0, 1.0);
461:           // Schlick Fresnel, water F0 ~0.02.
462:           float fres = 0.02 + 0.98 * pow(1.0 - ndv, 5.0);
463: 
464:           // Sky reflection tinted by the time-of-day gradient.  Grazing angles
465:           // reflect the warm horizon band; blending a little of the upper sky
466:           // in keeps the sea reading blue instead of dissolving into the haze.
467:           vec3 R = reflect(-viewDir, N);
468:           float skyMix = smoothstep(0.28, -0.04, R.y);
469:           vec3 skyRef = mix(uSkyTop, uSkyHorizon, skyMix * 0.62);
470:           vec3 sunDir = normalize(uSunDir);
471:           float sunR = max(dot(R, sunDir), 0.0);
472:           skyRef += uSunColor * pow(sunR, 120.0) * 1.1;
473:           skyRef += uSunColor * pow(sunR, 12.0) * 0.08;
474: 
475:           // Depth: turquoise shallows fading to deep Atlantic blue.
476:           float shoreDist = max(0.0, vWorld.x - uShoreX);
477:           float depthMix = smoothstep(0.0, 300.0, shoreDist);
478:           vec3 body = mix(uShallow, uDeep, depthMix);
479:           // Sub-surface glow on wave crests.
480:           body += uShallow * smoothstep(0.35, 1.15, vWave) * 0.14;
481: 
482:           // Sun specular + broad glitter path.
483:           vec3 H = normalize(sunDir + viewDir);
484:           float ndh = max(dot(N, H), 0.0);
485:           float spec = pow(ndh, 620.0);
486:           float glint = pow(ndh, 46.0);
487:           body += uSunColor * spec * 2.4;
488:           body += uSunColor * glint * 0.10;
489:           float sparkle = pow(ndh, 130.0) * smoothstep(0.55, 0.95, noise(q * 2.6 + uTime * 0.9));
490:           body += uSunColor * sparkle * 0.32;
491: 
492:           vec3 col = mix(body, skyRef, fres * 0.54);
493: 
494:           // Shore foam: lacy lines rolling up the wet sand.
495:           float shoreBand = 1.0 - smoothstep(0.0, 42.0, shoreDist);
496:           float drift = fbm(q * 0.48 + vec2(uTime * 0.5, -uTime * 0.2));
497:           float lines = sin(shoreDist * 0.85 - uTime * 2.3 + drift * 4.2) * 0.5 + 0.5;
498:           float lace = smoothstep(0.55, 0.93, lines)
499:                      * smoothstep(0.28, 0.76, fbm(q * 1.35 - vec2(uTime * 0.3, uTime * 0.22)));
500:           float wash = (1.0 - smoothstep(0.0, 8.0, shoreDist)) * 0.55;
501:           float foamShore = shoreBand * (lace * 0.9 + wash);
502:           // Whitecaps only on the tallest crests, kept small and broken up.
503:           float crestFoam = smoothstep(0.72, 1.0, vWave * 0.5 + 0.5)
504:                           * smoothstep(0.58, 0.92, fbm(q * 0.62 + vec2(uTime * 0.7, uTime * 0.3)))
505:                           * 0.14;
506:           float foam = clamp(foamShore + crestFoam, 0.0, 1.0);
507:           col = mix(col, uFoam, foam * 0.85);
508: 
509:           // Moonlit cool shift at night.
510:           col = mix(col, col * vec3(0.58, 0.72, 1.0), uNight * 0.38);
511: 
512:           // Aerial perspective.  The far Atlantic keeps a cool blue body and
513:           // only picks up a touch of warm haze, so the horizon stays a crisp
514:           // ocean line instead of blending into the sky.
515:           float dist = length(uCamPos - vWorld);
516:           vec3 farSea = mix(uDeep, uSkyTop, 0.38);
517:           float haze = smoothstep(650.0, 3400.0, dist);
518:           col = mix(col, farSea, haze * 0.62);
519:           col = mix(col, uFog, smoothstep(2400.0, 5200.0, dist) * 0.28);
520: 
521:           gl_FragColor = vec4(col, 1.0);
522:           #include <tonemapping_fragment>
523:           #include <colorspace_fragment>
524:         }`
525:     });
526:     this.water = new THREE.Mesh(geo, mat);
527:     // A borda oeste fica sob a areia molhada: as cristas lambem a praia
528:     // em vez de formar uma parede d'água na linha da trânsito.
529:     this.water.position.set(1890, -0.5, 0);
530:     this.water.frustumCulled = false;
531:     this.scene.add(this.water);
532:   }
