630:     for (const z of ROADS_Z) for (let x = -860; x < 566; x += 14) dashes.push([x, z, 1]);
631:     const dashMesh = new THREE.InstancedMesh(dashGeo, dashMat, dashes.length);
632:     const m = new THREE.Matrix4(); const q = new THREE.Quaternion(); const s = new THREE.Vector3(1, 1, 1);
633:     dashes.forEach((d, i) => {
