650:     // Crosswalks at central intersections
651:     const cwMat = new THREE.MeshBasicMaterial({ color: 0xe4ded0 });
652:     const cwGeo = new THREE.BoxGeometry(1.6, 0.012, 6);
653:     const cw = new THREE.InstancedMesh(cwGeo, cwMat, 12 * 12 * 2);
654:     let ci = 0;
655:     for (const x of [0, 280, -280, 140, -140, 560]) {
