690:     const poleMat = new THREE.MeshStandardMaterial({ color: 0x39434a, roughness: 0.7, metalness: 0.4 });
691:     const poles = new THREE.InstancedMesh(poleGeo, poleMat, n);
692:     const armGeo = new THREE.BoxGeometry(2.4, 0.14, 0.14);
