769:       this.waterUniforms.uDeep.value.set(p.waterDeep);
770:       this.waterUniforms.uShallow.value.set(p.waterShallow);
771:       this.waterUniforms.uFoam.value.set(p.waterFoam);
772:       this.waterUniforms.uFog.value.set(p.fog);
773:       this.waterUniforms.uSkyTop.value.set(p.skyTop);
774:       this.waterUniforms.uSkyHorizon.value.set(p.skyHorizon);
775:       this.waterUniforms.uSunColor.value.set(p.sun);
776:       this.waterUniforms.uSunDir.value.copy(this.sunDir);
