793:   update(dt, camera, playerPos) {
794:     this.time += dt;
795:     const t = this.time;
796:     if (this.waterUniforms) {
797:       this.waterUniforms.uTime.value = t;
798:       this.waterUniforms.uCamPos.value.copy(camera.position);
799:     }
800:     if (this.skyUniforms) this.skyUniforms.uTime.value = t;
801:     if (this.sky) this.sky.position.copy(camera.position);
802:     if (this.sunSprite) {
803:       this.sunSprite.position.copy(camera.position).addScaledVector(this.sunDir, 2300);
804:     }
805:     for (const c of this.clouds) {
806:       c.position.x += c.userData.speed * dt;
807:       if (c.position.x > 2200) c.position.x = -2200;
808:     }
809:     if (this.sunLight) {
810:       const p = playerPos || this._sunTargetPos.set(0, 0, 0);
811:       this.sunLight.position.set(p.x + this.sunDir.x * 260, this.sunDir.y * 320 + 60, p.z + this.sunDir.z * 260);
812:       this.sunLight.target.position.set(p.x, 0, p.z);
813:       this.sunLight.target.updateMatrixWorld();
814:     }
815:     for (const w of this.wheels) w.rotation.z += dt * 0.055;
816:     if (this.gondolas) {
817:       for (const g of this.gondolas) g.rotation.z = -this.wheelGroup.rotation.z;
818:     }
819:     if (this.lighthouseBeam) {
820:       this.lighthouseBeam.rotation.y += dt * 0.5;
821:     }
822:   }
823: }
