837: World.prototype._addCollider = function (x, z, w, d, h, type = 'building') {
838:   const c = { minX: x - w / 2, maxX: x + w / 2, minZ: z - d / 2, maxZ: z + d / 2, h, type };
839:   this.colliders.push(c);
840:   const cs = 80;
841:   const i0 = Math.floor(c.minX / cs), i1 = Math.floor(c.maxX / cs);
842:   const j0 = Math.floor(c.minZ / cs), j1 = Math.floor(c.maxZ / cs);
843:   for (let i = i0; i <= i1; i++) for (let j = j0; j <= j1; j++) {
844:     const key = i + ':' + j;
845:     let arr = this.colliderGrid.get(key);
846:     if (!arr) { arr = []; this.colliderGrid.set(key, arr); }
847:     arr.push(c);
848:   }
849:   return c;
850: };
