978: World.prototype._buildBuildingMesh = function () {
979:   const n = this.buildings.length;
980:   const geo = new THREE.BoxGeometry(1, 1, 1);
981:   const colors = new Float32Array(n * 3);
982:   const color = new THREE.Color();
983:   this.buildings.forEach((b, i) => {
984:     color.set(b.color);
985:     color.toArray(colors, i * 3);
986:   });
987:   geo.setAttribute('aColor', new THREE.InstancedBufferAttribute(colors, 3));
988: 
989:   const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.74, metalness: 0.13 });
990:   mat.onBeforeCompile = (shader) => {
991:     this.facadeShader = shader;
992:     shader.uniforms.uNight = { value: this.tod === 'night' ? 1 : 0 };
993:     shader.vertexShader = shader.vertexShader
994:       .replace('#include <common>', `#include <common>
995:         attribute vec3 aColor;
996:         varying vec3 vTint;
997:         varying vec3 vFacade;
998:         varying vec3 vFacadeNormal;`)
999:       .replace('#include <begin_vertex>', `#include <begin_vertex>
1000:         vTint = aColor;
1001:         vFacade = (instanceMatrix * vec4(position, 1.0)).xyz;
1002:         vFacadeNormal = normalize(mat3(instanceMatrix) * normal);`);
1003:     shader.fragmentShader = shader.fragmentShader
1004:       .replace('#include <common>', `#include <common>
1005:         varying vec3 vTint;
1006:         varying vec3 vFacade;
1007:         varying vec3 vFacadeNormal;
1008:         uniform float uNight;
1009:         float bHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }`)
1010:       .replace('#include <color_fragment>', `#include <color_fragment>
1011:         vec3 bn = normalize(vFacadeNormal);
1012:         float sideMask = 1.0 - step(0.55, abs(bn.y));
1013:         float bu = abs(bn.x) > 0.55 ? vFacade.z : vFacade.x;
1014:         float floorH = 3.55;
1015:         float colW = 3.15;
1016:         float fy = fract(vFacade.y / floorH);
1017:         float fx = fract(bu / colW);
1018:         float win = step(0.2, fx) * step(fx, 0.8) * step(0.3, fy) * step(fy, 0.78) * sideMask;
1019:         float cell = floor(vFacade.y / floorH) * 19.0 + floor(bu / colW) * 37.0;
1020:         float rnd = bHash(vec2(cell, 3.7));
1021:         vec3 glass = mix(vec3(0.055, 0.115, 0.14), vec3(0.22, 0.34, 0.38), rnd * 0.6);
1022:         diffuseColor.rgb *= vTint;
1023:         diffuseColor.rgb *= 1.0 - 0.1 * sideMask * step(0.88, fy);
1024:         diffuseColor.rgb = mix(diffuseColor.rgb, glass, win * 0.72);
1025:         diffuseColor.rgb = mix(diffuseColor.rgb, vTint * 0.62, step(0.55, abs(bn.y)) * 0.5);
1026:         float shop = step(vFacade.y, 3.4) * sideMask * step(0.42, fract(bu / 5.2));
