399:     }
400:     const sp = Math.min(1, speed / 4.5);
401:     this.walkPhase += dt * (3.2 + speed * 1.5);
402:     const swing = Math.sin(this.walkPhase) * 0.7 * sp;
403:     if (this.parts.legL) {
404:       this.parts.legL.rotation.x = swing;
405:       this.parts.legR.rotation.x = -swing;
406:     } else if (this.parts.l1) {
407:       this.parts.l1.rotation.x = swing * 0.7;
408:       this.parts.l2.rotation.x = -swing * 0.7;
409:     }
410:     if (this.parts.armL) {
411:       this.parts.armL.rotation.x = -swing * 0.75;
412:       if (state === 'aim') {
413:         this.parts.armR.rotation.x = -1.5;
414:         this.parts.armL.rotation.x = -1.25;
415:         this.parts.armL.rotation.z = 0.45;
416:         this.parts.gun.visible = true;
417:       } else if (state === 'shoot') {
418:         this.parts.armR.rotation.x = -1.62;
419:         this.parts.armL.rotation.x = -1.3;
420:         this.parts.gun.visible = true;
421:       } else {
422:         this.parts.armR.rotation.x = swing * 0.75;
423:         this.parts.armL.rotation.z = 0;
424:         this.parts.gun.visible = false;
425:       }
426:     } else if (this.parts.a1) {
427:       this.parts.a1.rotation.x = swing * 0.6;
428:       this.parts.a2.rotation.x = -swing * 0.6;
429:     }
430:     const bob = state === 'idle' ? Math.sin(this.walkPhase * 0.5) * 0.012 : Math.abs(Math.sin(this.walkPhase)) * 0.035 * sp;
431:     if (this.parts.hips) this.parts.hips.position.y = 0.94 + bob;
432:     else if (this.parts.torso) this.parts.torso.position.y = 1.22 + bob;
433:     if (this.parts.head) this.parts.head.position.y = 1.72 + bob * 0.6;
434:   }
